function Avatar({ initials, tone = 'sage', small = false }) {
  return <div className={`avatar avatar-${tone} ${small ? 'avatar-small' : ''}`}>{initials}</div>;
}

function Button({ children, variant = 'primary', onClick, className = '', icon }) {
  const fallback = () => window.dispatchEvent(new CustomEvent('planner-toast', { detail: `${typeof children === 'string' ? children : 'Action'} ready` }));
  return <button onClick={onClick || fallback} className={`button button-${variant} ${className}`}>{icon && <Icon name={icon} size={16} />}{children}</button>;
}

function StatusPill({ children, tone = 'green' }) { return <span className={`status-pill status-${tone}`}><span className="status-dot" />{children}</span>; }

function MetricCard({ metric }) {
  return <div className="metric-card">
    <div className="metric-top"><div className={`metric-icon metric-${metric.accent}`}><Icon name={metric.icon} size={18} /></div><span className={`metric-trend ${metric.trend === 'Healthy' ? 'trend-neutral' : ''}`}>{metric.trend}</span></div>
    <div className="metric-value">{metric.value}</div><div className="metric-label">{metric.label}</div><div className="metric-detail">{metric.detail}</div>
  </div>;
}

